export const isPaidAppointmentPresentation = (
  transactionTickets: Array<Pick<Transaction_ticket, 'isSettled'>>,
  isFakeMode: boolean,
): boolean =>
  transactionTickets.length > 0 &&
  transactionTickets.every(
    (item) => !shouldShowPayNowButton(item.isSettled, isFakeMode),
  );

export const formatAppointmentAmount = (amount: number): string => {
  const safeAmount = Number.isFinite(amount) ? amount : 0;
  const rounded = Math.round(safeAmount * 100) / 100;
  const isInteger = Number.isInteger(rounded);

  return new Intl.NumberFormat('en-US', {
    minimumFractionDigits: isInteger ? 0 : 2,
    maximumFractionDigits: isInteger ? 0 : 2,
  }).format(rounded);
};

export interface AppointmentDrugDetailView {
  drugName?: string;
  subTitle?: string;
  pictures?: {
    medium?: string;
  };
}

export interface AppointmentDrugView {
  key: string;
  name: string;
  detail: string;
  priceLabel: string;
  imageUri?: string;
  isFake: boolean;
}

export const FAKE_APPOINTMENT_DRUG: AppointmentDrugView = {
  key: 'fake-appointment-drug',
  name: 'Amlodipine (Norvasc 絡活喜)',
  detail: '5mg, ×1',
  priceLabel: 'HK$ 260',
  isFake: true,
};

export const buildAppointmentDrugViews = (
  drugs: TicketValueDrug[],
  details: Record<string, AppointmentDrugDetailView>,
  isFakeMode: boolean,
): AppointmentDrugView[] => {
  if (drugs.length === 0) {
    return isFakeMode ? [FAKE_APPOINTMENT_DRUG] : [];
  }

  return drugs.map((drug, index): AppointmentDrugView => {
    const detail = drug.productId ? details[drug.productId] : undefined;
    const subtitle = detail?.subTitle?.trim() ?? '';
    const quantity = drug.quantity ?? '';
    const price = Number(drug.price ?? 0);

    return {
      key: `${drug.productId ?? 'drug'}-${index}`,
      name: detail?.drugName || drug.name || '',
      detail: subtitle ? `${subtitle}, ×${quantity}` : `×${quantity}`,
      priceLabel: `HK$ ${formatAppointmentAmount(price)}`,
      imageUri: detail?.pictures?.medium,
      isFake: false,
    };
  });
};

