): boolean => isFakeMode && addressCount === 0;

export const FAKE_APPOINTMENT_PATIENT = {
  name: 'SampleName',
  phone: '+852 8123 1234',
};

export const resolveAppointmentPatient = (
  isFakeMode: boolean,
  name?: string,
  phone?: string,
): {name: string; phone: string} => {
  const trimmedName = name?.trim() ?? '';
  const trimmedPhone = phone?.trim() ?? '';

  if (!isFakeMode || trimmedName || trimmedPhone) {
    return {name: trimmedName, phone: trimmedPhone};
  }

  return FAKE_APPOINTMENT_PATIENT;
};

