const renderUpload = () => {
  return (
    <>
      <View style={styles.uploadRow}>
        <AppText style={styles.uploadText}>
          {$i18n.t("upload_msg")}
        </AppText>
        <GradientBt
          colors={THEME_BUTTON_COLORS}
          gradientStyle={styles.UploadBtn}
          disabled={state.uploading}
          style={{}}
          onPress={async () => {
            try {
              const files: Asset[] = await selectFile(
                "mixed",
                1
              );
              await uploadFile(files[0], (progress: number) => {
                setState((prevState) => {
                  return {
                    ...prevState,
                    uploadProgress: progress,
                  };
                });
              });
            } catch (error) {}
          }}
        >
          <AppText size='small' style={{ paddingHorizontal: 16, color: '#FFFFFF' }}>
            {$i18n.t("upload")}
          </AppText>
        </GradientBt>
      </View>
      {state.uploading && (
        <LinearProgress
          value={state.uploadProgress / 100}
          style={styles.progressBar}
          color="#2e7d32"
          trackColor="#a5d6a7"
          variant="determinate"
        />
      )}
      {state.uploadedFilesList.map(
        (file: UploadedFilesList, index) => (
          <TouchableOpacity
            key={index}
            style={styles.uploadedFileRow}
            onPress={async () => {
              if (file.name) {
                setLoadingText($i18n.t("loading"));
                setLoading(true);
                try {
                  const response: Files_ticket_getOneFile_response =
                    await $api.files_ticket_getOneFile(
                      state.ticketId,
                      file.name
                    );
                  const internalPath =
                    await saveFileToInternalStorage(
                      response.data,
                      file.name
                    );
                  if (internalPath) {
                    openFileWithFileViewer(internalPath);
                  }
                } catch (error) {}
                setLoading(false);
              }
            }}
          >
            <View style={styles.fileIcon}>
              {state.svgData_fileIcon ? (
                <SvgXml
                  xml={state.svgData_fileIcon}
                  width="100%"
                  height="100%"
                />
              ) : null}
            </View>
            <AppText style={styles.uploadedFileName}>
              {file.name}
            </AppText>
            <TouchableOpacity
              style={styles.uploadedFileRowCloseBt}
              onPress={async () => {
                if (file.name) {
                  try {
                    const response: Response =
                      await $api.files_ticket_del(
                        state.ticketId,
                        file.name
                      );
                    if (response.success) {
                      const _uploadedFilesList =
                        state.uploadedFilesList.filter(
                          (currentValue, index, arr) => {
                            return (
                              currentValue.name !== file.name
                            );
                          }
                        );
                      setState((prevState) => {
