const openUploadedFile = async (fileName?: string) => {
  if (!fileName) {
    return;
  }

  setLoadingText($i18n.t("loading"));
  setLoading(true);
  try {
    const response: Files_ticket_getOneFile_response =
      await $api.files_ticket_getOneFile(
        state.ticketId,
        fileName
      );
    const internalPath = await saveFileToInternalStorage(
      response.data,
      fileName
    );
    if (internalPath) {
      openFileWithFileViewer(internalPath);
    }
  } catch (error) {}
  setLoading(false);
};

const removeUploadedFile = async (fileName?: string) => {
  if (!fileName) {
    return;
  }

  try {
    const response: Response = await $api.files_ticket_del(
      state.ticketId,
      fileName
    );
    if (response.success) {
      setState((prevState) => {
        return {
          ...prevState,
          uploadedFilesList: prevState.uploadedFilesList.filter(
            (currentValue) => currentValue.name !== fileName
          ),
        };
      });
    }
  } catch (e) {}
};

