const downloadReceipt = async (country: string) => {
  setLoadingText($i18n.t("loading"));
  setLoading(true);
  try {
    const res: PrescriptionFiles = await $api.getReceipt(
      state.ticket?.id || "",
      country,
      country
    );
    const supported = await Linking.canOpenURL(res.fileUrl);
    if (supported) {
      await Linking.openURL(res.fileUrl);
    }
  } catch (e) {}
  setLoading(false);
};

const renderDocumentRow = (
  key: string,
  name: string,
  onPress: () => void,
) => (
  <TouchableOpacity
    key={key}
    style={styles.documentFileRow}
    onPress={onPress}
  >
    <View style={styles.fileIcon}>
      <PdfFillIcon width={11.33} height={13.33} />
    </View>
    <AppointmentLabel numberOfLines={1} style={styles.uploadedFileName}>
      {name}
    </AppointmentLabel>
    <View style={styles.uploadedFileAction}>
      <DownloadFillIcon width={16} height={16} />
    </View>
  </TouchableOpacity>
);

const renderDocumentsAvailable = (
  prescriptionLanguagesArray: string[],
  allPaid: boolean,
) => {
  if (!state.ticket) {
    return null;
  }

  const status = state.ticket.ticketStatus;
  const canShowRealDocuments = status === "consulted" || status === "completed";
  const groups: Array<{
    key: string;
    title: string;
    rows: Array<{ key: string; name: string; onPress: () => void }>;
  }> = [];

  if (status === "completed") {
    const prescriptions = state.ticket.consultation?.prescriptions;
    if (prescriptions && prescriptions.length > 0) {
      groups.push({
        key: "prescription",
        title: $i18n.t("prescription"),
        rows: prescriptionLanguagesArray.map((country, index) => ({
          key: `prescription-${country}-${index}`,
          name: `${$i18n.t("prescription")}_${getLangByCountry(country || "Singapore")}.pdf`,
          onPress: () => {
            void handleGetDocumentAvailable(country);
          },
        })),
      });
    }

    const certificates = state.ticket.consultation?.documents?.medicalCertificates ?? [];
    if (certificates.length > 0) {
      groups.push({
        key: "medical-certificate",
        title: $i18n.t("medicalCertificate"),
        rows: certificates.map((listItem, index) => ({
          key: `certificate-${listItem.fileName ?? index}`,
          name: listItem.fileName ?? $i18n.t("medicalCertificate"),
          onPress: () => {
            void handleDownloadMedicalCertificate(listItem);
          },
        })),
      });
    }

    const referrals = state.ticket.consultation?.documents?.referralLetters ?? [];
    if (referrals.length > 0) {
      groups.push({
        key: "referral",
        title: $i18n.t("referralLetter"),
        rows: referrals.map((listItem, index) => ({
          key: `referral-${listItem.fileName ?? index}`,
          name: listItem.fileName ?? $i18n.t("referralLetter"),
          onPress: () => {
            void handleDownloadReferralLetter(listItem);
          },
        })),
      });
    }

    if (allPaid && (state.transaction_ticket?.length ?? 0) > 0) {
      groups.push({
        key: "receipt",
        title: $i18n.t("appointment_invoice_documents"),
        rows: prescriptionLanguagesArray.map((country, index) => ({
          key: `receipt-${country}-${index}`,
          name: `${$i18n.t("receipt")}_${getLangByCountry(country || "Singapore")}.pdf`,
          onPress: () => {
            void downloadReceipt(country);
          },
        })),
      });
    }
  }

  const orderedGroups = [
    ...groups.filter((group) => group.key === "receipt"),
    ...groups.filter((group) => group.key === "prescription"),
    ...groups.filter((group) => group.key !== "receipt" && group.key !== "prescription"),
  ].filter((group) => group.rows.length > 0);
  const realDocumentCount = orderedGroups.reduce(
    (count, group) => count + group.rows.length,
    0,
  );
  const useFakeDocuments = shouldUseFakeAppointmentDocuments(
    $fake,
    realDocumentCount,
  );

  if (!canShowRealDocuments && !useFakeDocuments) {
    return null;
  }

  const documentsTitle = $i18n.t("appointment_documents_title");

  if (useFakeDocuments) {
    return (
      <SectionCard
        icon={<FileLinesFillIcon width={24} height={24} />}
        title={documentsTitle}
        titleBorder="none"
      >
        <View style={styles.documentGroups}>
          {FAKE_APPOINTMENT_DOCUMENT_GROUPS.map((group) => (
            <View key={group.id} style={styles.documentGroup}>
              <AppointmentLabel style={styles.documentGroupTitle}>
                {$i18n.t(group.titleKey)}
              </AppointmentLabel>
              {group.files.map((file) =>
                renderDocumentRow(file.id, file.name, () => undefined)
              )}
            </View>
          ))}
        </View>
      </SectionCard>
    );
  }

  if (status === "consulted") {
    return (
      <SectionCard
        icon={<FileLinesFillIcon width={24} height={24} />}
        title={documentsTitle}
        titleBorder="none"
      >
        <AppText style={styles.payment_for_doc_text}>
          {$i18n.t("payment_for_doc")}
        </AppText>
      </SectionCard>
    );
  }

  if (orderedGroups.length === 0) {
    return (
      <SectionCard
        icon={<FileLinesFillIcon width={24} height={24} />}
        title={documentsTitle}
        titleBorder="none"
      >
        <AppText style={styles.documents_not_available_txt}>
          {$i18n.t("documents_not_available")}
        </AppText>
      </SectionCard>
    );
  }

  return (
    <SectionCard
      icon={<FileLinesFillIcon width={24} height={24} />}
      title={documentsTitle}
      titleBorder="none"
    >
      <View style={styles.documentGroups}>
        {orderedGroups.map((group) => (
          <View key={group.key} style={styles.documentGroup}>
            <AppointmentLabel style={styles.documentGroupTitle}>
              {group.title}
            </AppointmentLabel>
            {group.rows.map((row) =>
              renderDocumentRow(row.key, row.name, row.onPress)
            )}
          </View>
        ))}
      </View>
    </SectionCard>
  );
};

