const readBlobAsBase64 = (blob: Blob): Promise<string | undefined> =>
  new Promise((resolve) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const result = reader.result;
      resolve(typeof result === 'string' ? result.split(',')[1] : undefined);
    };
    reader.onerror = () => resolve(undefined);
    reader.readAsDataURL(blob);
  });

const openPdfFromUrl = async (url: string, title: string) => {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`fetch pdf failed: ${response.status}`);
