  const blob = await response.blob();
  const base64Data = await readBlobAsBase64(blob);
  if (!base64Data) {
    throw new Error('empty pdf');
  }
  $NavigationActions.navigate($routeNames.pdfScreen, {
    title,
    source: { uri: `data:application/pdf;base64,${base64Data}` },
  });
};

