export const listAppointmentDocumentCountries = (
  countries: Array<string | undefined>,
): string[] => {
  const seen = new Set<string>();
  const result: string[] = [];

  countries.forEach((country) => {
    const trimmed = country?.trim();
    if (!trimmed) {
      return;
    }
    const key = trimmed.toLowerCase();
    if (seen.has(key)) {
      return;
    }
    seen.add(key);
    result.push(trimmed);
  });

  return result;
};

